contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint lockTime, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // Only test lockTime values where block.timestamp + lockTime overflows in Solidity.
        require(lockTime > type(uint).max - block.timestamp);
        // Ensure no other overflow affects the balance update.
        require(address(this).balance >= amount);

        (uint unlockBefore, uint balBefore) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        require(balBefore + amount >= balBefore);

        bool reverted;
        c.Put{value: amount}(lockTime); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        (uint unlockAfter, uint balAfter) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        // The call may revert, but if it does, the caller's account must be unchanged.
        assert(!reverted || (balAfter == balBefore && unlockAfter == unlockBefore));
    }

    receive() external payable {}
}

